  insert into lessons (unit_id, position, title, kind, body, est_minutes) values (u_id,1,'Voltooide tijd met hebben en zijn','grammar',$j${"intro": "Je leert de voltooide tijd maken met hebben of zijn en het voltooid deelwoord.", "vocab": ["bestellen", "vergeten", "aankomen"], "sections": [{"type": "text", "title": "Hebben of zijn", "paragraphs": ["De voltooide tijd bestaat uit een hulpwerkwoord en een voltooid deelwoord. De meeste werkwoorden gebruiken hebben: Ik heb gewerkt.", "Werkwoorden van beweging naar een plaats of van verandering gebruiken zijn, bijvoorbeeld gaan, komen, vertrekken, aankomen, blijven en worden: Ik ben naar Utrecht gegaan.", "Een regelmatig voltooid deelwoord is ge- plus de stam plus t of d: gewerkt, gehoord. Na t, k, f, s, ch of p komt een t. Werkwoorden met be-, ver- of ont- krijgen geen ge-: besteld, vergeten."], "examples": [{"nl": "Ik heb gisteren de hele dag gewerkt.", "note": "Werken gebruikt hebben."}, {"nl": "Wij zijn om negen uur aangekomen.", "note": "Aankomen is een beweging naar een plaats en gebruikt zijn."}, {"nl": "Ik heb een taxi besteld.", "note": "Bestellen begint met be- en krijgt geen ge-."}, {"nl": "Zij hebben pasta gegeten.", "note": "Eten is onregelmatig: gegeten."}, {"nl": "Ik ben naar Utrecht gegaan.", "note": "Gaan gebruikt zijn.", "wrong": "Ik heb naar Utrecht gegaan."}]}, {"type": "exercises", "items": [{"kind": "mcq", "tag": "hulpwerkwoord", "prompt": "Gisteren ___ ik naar de markt gegaan.", "options": ["heb", "ben", "is"], "answer": 1, "explanation": "Gaan is een beweging en gebruikt zijn: ik ben gegaan."}, {"kind": "mcq", "tag": "hulpwerkwoord", "prompt": "Zij ___ de hele dag gewerkt.", "options": ["is", "heeft", "hebben"], "answer": 1, "explanation": "Werken gebruikt hebben. Bij zij enkelvoud hoort heeft."}, {"kind": "gap", "tag": "deelwoord", "prompt": "Wij hebben gisteren pasta ___ (eten).", "answers": ["gegeten"], "explanation": "Eten is onregelmatig: gegeten."}, {"kind": "gap", "tag": "deelwoord", "prompt": "Ik heb een taxi ___ (bestellen).", "answers": ["besteld"], "explanation": "Bestellen begint met be-, dus zonder ge-."}, {"kind": "gap", "tag": "deelwoord", "prompt": "Hij is te laat ___ (komen).", "answers": ["gekomen"], "explanation": "Komen gebruikt zijn en vormt gekomen."}, {"kind": "mcq", "tag": "deelwoord", "prompt": "Wat is het voltooid deelwoord van koken?", "options": ["gekookt", "gekoken", "gekokt"], "answer": 0, "explanation": "De stam kook eindigt op k, dus komt er een t: gekookt."}]}]}$j$::jsonb,14) on conflict (unit_id, position) do nothing;
  insert into lessons (unit_id, position, title, kind, body, est_minutes) values (u_id,2,'Scheidbare werkwoorden','grammar',$j${"intro": "Je leert waar het scheidbare deel van een werkwoord staat in hoofdzinnen, bijzinnen en de voltooide tijd.", "vocab": ["uitnodigen", "meenemen", "terugkomen", "opbellen"], "sections": [{"type": "text", "title": "Scheidbare werkwoorden", "paragraphs": ["Een scheidbaar werkwoord heeft een voorvoegsel dat los kan komen, zoals op, uit, mee en terug. In een hoofdzin staat de persoonsvorm op de tweede plaats en het voorvoegsel aan het einde: Ik bel je morgen op.", "In een bijzin blijft het werkwoord heel en staat het aan het einde: Ik hoop dat hij je morgen opbelt.", "In de voltooide tijd komt ge- tussen het voorvoegsel en de stam: Ik heb je gisteren opgebeld. Ze hebben mijn boek meegenomen."], "examples": [{"nl": "Ik sta om zeven uur op.", "note": "Het voorvoegsel op staat aan het einde."}, {"nl": "Zij nodigt ons morgen uit.", "note": "Uitnodigen is scheidbaar."}, {"nl": "Wanneer kom je terug?", "note": "Terugkomen is scheidbaar."}, {"nl": "Ik hoop dat hij je morgen opbelt.", "note": "In de bijzin staat opbelt aan het einde in één woord."}, {"nl": "Heb je mijn boek meegenomen?", "note": "Het deelwoord is mee + ge + nomen."}]}, {"type": "exercises", "items": [{"kind": "mcq", "tag": "scheidbaar", "prompt": "Kies de juiste zin.", "options": ["Ik sta om zeven uur op.", "Ik opsta om zeven uur.", "Ik om zeven uur sta op."], "answer": 0, "explanation": "Het voorvoegsel op gaat naar het einde van de hoofdzin."}, {"kind": "gap", "tag": "scheidbaar", "prompt": "Zij nodigt ons morgen ___.", "answers": ["uit"], "explanation": "Uitnodigen: zij nodigt ons uit."}, {"kind": "mcq", "tag": "scheidbaar", "prompt": "Ik hoop dat hij je morgen ___.", "options": ["opbelt", "belt op", "op belt"], "answer": 0, "explanation": "In een bijzin blijft het scheidbare werkwoord in één woord aan het einde."}, {"kind": "gap", "tag": "scheidbaar", "prompt": "Heb je mijn boek ___ (meenemen)?", "answers": ["meegenomen"], "explanation": "Het deelwoord van meenemen is meegenomen."}, {"kind": "gap", "tag": "scheidbaar", "prompt": "Wanneer kom je ___?", "answers": ["terug"], "explanation": "Terugkomen: het voorvoegsel terug staat aan het einde."}]}]}$j$::jsonb,14) on conflict (unit_id, position) do nothing;
  insert into lessons (unit_id, position, title, kind, body, est_minutes) values (u_id,3,'Modale werkwoorden en beleefd vragen','grammar',$j${"intro": "Je gebruikt kunnen, moeten, willen en mogen met de infinitief aan het einde van de zin.", "vocab": ["verplicht", "verboden"], "sections": [{"type": "text", "title": "Modale werkwoorden", "paragraphs": ["Kunnen, moeten, willen, mogen en zullen staan in een hoofdzin op de tweede plaats. De infinitief staat aan het einde: Ik moet morgen vroeg opstaan.", "Moeten betekent dat het verplicht is. Mogen betekent dat het is toegestaan. Kunnen gaat over mogelijkheid of vaardigheid. Willen gaat over wat je zelf wilt.", "Je maakt een vraag of verzoek beleefder met zou je ... kunnen: Zou je me de pen kunnen geven?"], "examples": [{"nl": "Je mag hier niet roken.", "note": "Het is verboden."}, {"nl": "Je moet je paspoort meenemen.", "note": "Het is verplicht."}, {"nl": "Mag ik hier even zitten?", "note": "Je vraagt toestemming."}, {"nl": "Zou je me kunnen helpen?", "note": "Beleefder dan Kun je me helpen?"}]}, {"type": "exercises", "items": [{"kind": "mcq", "tag": "modaal", "prompt": "Je mag hier niet roken. Wat betekent dat?", "options": ["Het is verboden.", "Het is verplicht.", "Het is gezellig."], "answer": 0, "explanation": "Niet mogen betekent dat iets verboden is."}, {"kind": "mcq", "tag": "modaal", "prompt": "Je ___ je paspoort meenemen. Het is verplicht.", "options": ["moet", "mag", "wil"], "answer": 0, "explanation": "Moeten drukt verplichting uit."}, {"kind": "gap", "tag": "modaal", "prompt": "___ ik hier even zitten?", "answers": ["mag", "kan"], "explanation": "Je vraagt toestemming met mag ik of kan ik."}, {"kind": "mcq", "tag": "woordvolgorde", "prompt": "Kies de juiste zin.", "options": ["Ik moet morgen vroeg opstaan.", "Ik moet morgen opstaan vroeg.", "Ik moet opstaan morgen vroeg."], "answer": 0, "explanation": "Moeten staat op plaats twee en de infinitief opstaan staat aan het einde."}, {"kind": "mcq", "tag": "register", "prompt": "Welke zin is het beleefdst?", "options": ["Geef me de pen.", "Zou je me de pen kunnen geven?", "Pen geven."], "answer": 1, "explanation": "Zou je ... kunnen maakt een verzoek beleefd."}]}]}$j$::jsonb,12) on conflict (unit_id, position) do nothing;
  insert into lessons (unit_id, position, title, kind, body, est_minutes) values (u_id,4,'Bij de huisarts','listening',$j${"intro": "Je belt de huisartsenpraktijk om een afspraak te maken.", "vocab": ["last hebben van", "vervelend", "praktijk", "zorgpas", "Waar gaat het over?", "Dat is vervelend", "Dat komt niet goed uit", "Dat past", "Graag gedaan"], "sections": [{"type": "dialogue", "title": "Een afspraak bij de huisarts", "lines": [{"speaker": "Assistent", "voice": "colette", "text": "Huisartsenpraktijk De Linde, goedemorgen."}, {"speaker": "Peters", "voice": "maarten", "text": "Goedemorgen, mijn naam is Peters. Ik wil graag een afspraak maken."}, {"speaker": "Assistent", "voice": "colette", "text": "Waar gaat het over?"}, {"speaker": "Peters", "voice": "maarten", "text": "Ik heb al een week last van mijn rug."}, {"speaker": "Assistent", "voice": "colette", "text": "Dat is vervelend. Kunt u vanmiddag om kwart over drie komen?"}, {"speaker": "Peters", "voice": "maarten", "text": "Dat komt niet goed uit. Dan moet ik werken. Heeft u ook iets in de ochtend?"}, {"speaker": "Assistent", "voice": "colette", "text": "Morgen om negen uur is er ruimte."}, {"speaker": "Peters", "voice": "maarten", "text": "Dat past. Dank u wel."}, {"speaker": "Assistent", "voice": "colette", "text": "Graag gedaan. Neemt u uw zorgpas mee?"}], "expressions": [{"nl": "Waar gaat het over?", "meaning_nl": "Je vraagt naar het onderwerp of de reden.", "register": "neutraal"}, {"nl": "Dat is vervelend", "meaning_nl": "Je laat horen dat je medeleven hebt.", "register": "neutraal"}, {"nl": "Dat komt niet goed uit", "meaning_nl": "Dat past niet in mijn planning.", "register": "neutraal"}, {"nl": "Dat past", "meaning_nl": "Dat is goed voor mij.", "register": "informeel"}, {"nl": "Graag gedaan", "meaning_nl": "Je antwoordt zo op dank.", "register": "neutraal"}]}, {"type": "exercises", "items": [{"kind": "mcq", "tag": "luisteren", "prompt": "Waarom belt meneer Peters?", "options": ["Hij wil een afspraak maken.", "Hij wil een recept.", "Hij heeft zijn pas verloren."], "answer": 0, "explanation": "Hij zegt dat hij een afspraak wil maken."}, {"kind": "mcq", "tag": "luisteren", "prompt": "Hoe lang heeft hij last van zijn rug?", "options": ["Een dag", "Een week", "Een maand"], "answer": 1, "explanation": "Hij heeft al een week last."}, {"kind": "mcq", "tag": "luisteren", "prompt": "Waarom komt de middag niet goed uit?", "options": ["Hij moet werken.", "Hij is op vakantie.", "De praktijk is dicht."], "answer": 0, "explanation": "Hij zegt: dan moet ik werken."}, {"kind": "mcq", "tag": "luisteren", "prompt": "Wanneer wordt de afspraak?", "options": ["Vanmiddag om kwart over drie", "Morgen om negen uur", "Vrijdag"], "answer": 1, "explanation": "Morgen om negen uur is er ruimte en dat past hem."}, {"kind": "gap", "tag": "uitdrukking", "prompt": "Om negen uur? Dat ___.", "answers": ["past"], "explanation": "Dat past betekent dat het goed uitkomt."}, {"kind": "dictation", "tag": "dictee", "text": "Dat komt niet goed uit.", "voice": "maarten", "explanation": "Schrijf precies wat je hoort."}]}]}$j$::jsonb,15) on conflict (unit_id, position) do nothing;
  insert into lessons (unit_id, position, title, kind, body, est_minutes) values (u_id,5,'Je mening geven','vocabulary',$j${"intro": "Je leert je mening geven en beleefd zeggen dat je het ergens niet mee eens bent.", "vocab": ["mening", "oplossing", "aanpassen", "Volgens mij", "Ik zie het anders", "Dat hangt ervan af"], "sections": [{"type": "text", "title": "Je mening geven", "paragraphs": ["Je begint een mening met Volgens mij, Ik vind dat of Naar mijn mening. Na Ik vind dat staat de persoonsvorm aan het einde van de bijzin.", "Als je het niet eens bent, zeg je het beleefd met Ik zie het anders of Daar ben ik het niet mee eens. Geef daarna een reden met want of omdat.", "Als je het antwoord niet in één woord kunt geven, zeg je Dat hangt ervan af."], "examples": [{"nl": "Volgens mij is thuiswerken prettiger.", "note": "Na Volgens mij blijft de normale volgorde van een hoofdzin."}, {"nl": "Ik vind dat we de planning moeten aanpassen.", "note": "Moeten aanpassen staan aan het einde van de bijzin."}, {"nl": "Ik zie het anders, want de oplossing is te duur.", "note": "Beleefde afwijzing met een reden."}, {"nl": "Dat hangt ervan af hoeveel tijd we hebben.", "note": "Je noemt de voorwaarde."}]}, {"type": "exercises", "items": [{"kind": "mcq", "tag": "mening", "prompt": "Je bent het niet eens met je collega. Wat zeg je beleefd?", "options": ["Ik zie het anders.", "Dat is onzin.", "Nee, hoor jij maar."], "answer": 0, "explanation": "Ik zie het anders is beleefd en duidelijk."}, {"kind": "gap", "tag": "mening", "prompt": "Ik ___ dat we eerder moeten beginnen.", "answers": ["vind"], "explanation": "Ik vind dat introduceert een mening."}, {"kind": "gap", "tag": "mening", "prompt": "___ mij is dit de beste oplossing.", "answers": ["Volgens"], "explanation": "Volgens mij is een vaste uitdrukking voor een mening."}, {"kind": "mcq", "tag": "woordvolgorde", "prompt": "Kies de juiste zin.", "options": ["Ik vind dat we de planning moeten aanpassen.", "Ik vind dat we moeten de planning aanpassen.", "Ik vind dat moeten we de planning aanpassen."], "answer": 0, "explanation": "In de bijzin staan de persoonsvorm en de infinitief aan het einde."}, {"kind": "dictation", "tag": "dictee", "text": "Ik zie het anders.", "voice": "fenna", "explanation": "Schrijf precies wat je hoort."}]}]}$j$::jsonb,12) on conflict (unit_id, position) do nothing;
insert into texts (level_code, genre, title, content, register, questions) select 'B1','brief','Een brief van de gemeente',$c$Geachte mevrouw Jansen,
insert into texts (level_code, genre, title, content, register, questions) select 'B1','verhaal','Een lange dag',$c$Om half zeven ging de wekker af, maar Daan stond pas om zeven uur op. Hij had geen tijd om te ontbijten en rende naar de bus. Op kantoor wachtte een vervelende verrassing: de koffiemachine was kapot. "Dat ook nog," zei hij tegen zijn collega Fatima. Zij lachte en nodigde hem uit voor een kop thee in haar kamer. Daar vertelde ze dat ze volgende maand naar Rotterdam verhuist. Daan was blij voor haar, maar ook een beetje verdrietig. Aan het eind van de dag fietste hij naar huis en dacht: toch was het een goede dag.$c$,'informal',$j${"glossary": [{"nl": "Dat ook nog", "meaning_nl": "je zegt dit als er nog een probleem bijkomt"}, {"nl": "de wekker gaat af", "meaning_nl": "de wekker maakt geluid om je wakker te maken"}, {"nl": "rennen", "meaning_nl": "heel snel lopen"}], "questions": [{"kind": "mcq", "tag": "lezen", "prompt": "Waarom ontbeet Daan niet?", "options": ["Hij had geen tijd.", "Hij had geen honger.", "Er was geen brood."], "answer": 0, "explanation": "Hij had geen tijd om te ontbijten."}, {"kind": "mcq", "tag": "lezen", "prompt": "Wat was er kapot op kantoor?", "options": ["De printer", "De koffiemachine", "De lift"], "answer": 1, "explanation": "De koffiemachine was kapot."}, {"kind": "mcq", "tag": "lezen", "prompt": "Waar gaat Fatima naartoe verhuizen?", "options": ["Utrecht", "Rotterdam", "Groningen"], "answer": 1, "explanation": "Ze verhuist volgende maand naar Rotterdam."}]}$j$::jsonb where not exists (select 1 from texts where title='Een lange dag');
